import { test, expect } from '@playwright/test';

test.describe('Main Layout Horizontal Scrolling', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://yourwebsite.com'); // Replace with your actual URL
  });

  test('should not allow horizontal scrolling on mobile', async ({ page }) => {
    await page.setViewportSize({ width: 375, height: 812 }); // Set mobile viewport
    const body = await page.getByRole('document');
    const overflowX = await body.evaluate(el => getComputedStyle(el).overflowX);
    expect(overflowX).toBe('hidden');
  });

  test('should display content correctly without horizontal scrolling', async ({ page }) => {
    await page.setViewportSize({ width: 375, height: 812 }); // Set mobile viewport
    const content = await page.getByText('Expected Content'); // Replace with actual content
    await expect(content).toBeVisible();
    const contentBoundingBox = await content.boundingBox();
    expect(contentBoundingBox).not.toBeNull();
    expect(contentBoundingBox!.width).toBeLessThanOrEqual(375); // Ensure content fits within viewport
  });
});
